"""Run one new read-only GPT-6.1 Sol Issue 1 final review: engineer|validation."""
from pathlib import Path
from datetime import datetime,timezone
import json,hashlib,subprocess,sys,shutil
root=Path.cwd();role=sys.argv[1];assert role in ['engineer','validation'];out=root/'results/reviews/issue-1'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
docpaths=['docs/guidelines/mysql.md','docs/guidelines/sql-server.md','docs/README.md','docs/guidelines/operations-runbook.md'];docs={p:sha(root/p) for p in docpaths}
