if role=='validation':assert (out/'final-engineer-result.json').is_file()
inputs={'documents':docs,'baselineSha256':sha(out/'baseline.json'),'issueSha256':sha(out/'issue.json'),'ownerProofSha256':sha(out/'owner-proof.json'),'ownerAuditSha256':sha(out/'owner-audit.json'),'runtimeArchiveManifestSha256':proof['archiveManifestSha256'],'sourceHashes':proof['sourceHashes']}
prompt='You are GPT-6.1 Sol independent adversarial reviewer in a NEW read-only session separate from author and other reviewer. Role ROLE. Read AGENTS.md and results/reviews/issue-1/issue.json in full. Do not modify any file, start Docker/DB/measurements, delegate, run workflows, commit or publish. Review final current docs/guidelines/{mysql.md,sql-server.md,operations-runbook.md}, docs/README.md and sqlserver/issue1 implementation/evidence. Goal: resolve all FOUR Issue 1 items concretely for unfamiliar engineers safely obtaining whole-table row counts. This is an Issue remediation, not a new huge benchmark or certification of production SLO. Existing immutable measurements/receipts must remain unchanged, accepted old docs archived and new hash-bound receipt used.\nVerify actual file hashes against baseline protectedFiles, owner-proof sourceHashes, runtime result before/after and manifest. Independently inspect raw probe.json/controller log/actual plans in runtimeArchive, not only aggregate passed flags. Verify the 5 actual cases, two separate SQL connections, server connection_id vs ClientConnectionId, CONTEXT_INFO visible to observer, all identity fields and permission preflight, 3 mismatch refusals and original owner usability, permission-denied/partial visibility unknown. For server error, clientCancel and timeout request absence must coexist with sleeping open TX/snapshot before finally. Fresh bounded cleanup token must not inherit cancelled work token. Own rollback and guard-checked management KILL paths, retained TX IDs including active_transactions after session mapping gone, session/request/TX/snapshot release and exact resource ownership/cleanup must be sound. KILL has residual SPID TOCTOU; cannot claim atomic identity cancellation. Idle Dispose is only communication-failure simulation, not actual partition; unusable/unreachable observer=>UNKNOWN/no next work/escalation. No native/prod recovery or physical allocation reclaimed claims from this functional probe.\nFor auto stats verify old OFF lab limitation, explicit existing sync/async/lowpriority/compat/state capture, plain unfiltered COUNT only, actual plan/OptimizerStatsUsage vs namedstats timestamps/modcounter/rows before/after, bounded cumulative observation windows and async/XE limitations. No universal COUNT triggers/never triggers claim and no production blanket flag toggles. For operational bridge examine blank plus FILLED independent restored copy and dedicated replica examples, explicit fictional illustrative_not_measured data not recommended thresholds, shared CPU/memory/storage/device/network/primary effects, actual caps mechanism verification or HOLD, metric source/privileges/unavailable not0, normal variability, detection/aggregate/delivery/decision/cancel/rollback/jitter upper budget vs measured time-to-risk not conversion from p99msdelta, recovery/owner and pending-arrival SLO accounting. MySQL MDL/undo/applier + SQL request/TX/version/PVS/AG primary recovery concrete observations. Ordinary COUNT no rowlock does not mean zero MDL; no new intentional contention injection. Do not insist on full performance grid or real network partition experiment where guide explicitly defers all unverified cases safely. Request experiment only indispensable to a current operative claim; doc correction is sufficient when it removes that claim.\nFirst form independent findings. ROLEFOLLOWUP\nReturn concise JSON accepted(bool), decision accepted/rejected, documentHashes exact current 4doc hashes, findings with stableid/severity high|middle|low and concrete scenario/fix, requestedExperiments, reviewQuestions {betterMethods,designCoverage,omissions,lockFactors,fastCount}, coverageReport mapping Issue1 items1-4 to evidence/pass or fail, reviewEvidence paths/hashes/observations. No high/middle or indispensable experiment may remain at acceptance. Aggregate acceptance.json pending until both reviews finish; do not require prior accepted receipt. Do not waive defects. Low optional improvements can remain if no unsafe recommendation.\n'.replace('ROLEFOLLOWUP', 'Then read results/reviews/issue-1/final-engineer-result.json and assess its findings in independentFindingAssessment.' if role=='validation' else '').replace('ROLE',role)
prompt+='\nExact inputs: '+json.dumps(inputs)
name='temp-issue1-final-'+role+'-sol';base=root/'.private.handover/issue1-final-temp-workflows';dest=base/name;(dest/'nodes').mkdir(parents=True,exist_ok=True)
node={'id':'review','executionBackend':'codex-agent','model':'gpt-6.1-sol','modelFreeze':True,'effort':'high','agentSandbox':'read-only','sessionPolicy':{'mode':'new'},'variables':{},'promptTemplate':prompt,'output':{'jsonSchema':{'type':'object','required':['accepted','decision','documentHashes','findings','requestedExperiments','reviewQuestions','coverageReport','reviewEvidence'],'properties':{'accepted':{'type':'boolean'},'decision':{'enum':['accepted','rejected']},'documentHashes':{'type':'object'},'findings':{'type':'array'},'requestedExperiments':{'type':'array'},'reviewQuestions':{'type':'object'},'coverageReport':{'type':'object'},'reviewEvidence':{'type':'array'}},'additionalProperties':True},'maxValidationAttempts':2}}
wf={'workflowId':name,'description':'Issue 1 final adversarial remediation review '+role,'defaults':{'nodeTimeoutMs':3600000,'maxLoopIterations':1},'entryStepId':'review','nodes':[{'id':'review','nodeFile':'nodes/review.json'}],'steps':[{'id':'review','nodeId':'review','role':'worker'}]}
(dest/'workflow.json').write_text(json.dumps(wf,indent=2)+'\n');(dest/'nodes/review.json').write_text(json.dumps(node,ensure_ascii=False,indent=2)+'\n')
stamp=datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ');attempt=out/(role+'-'+stamp);attempt.mkdir()
for p in docpaths+['results/reviews/issue-1/baseline.json','results/reviews/issue-1/issue.json','results/reviews/issue-1/owner-proof.json','results/reviews/issue-1/owner-audit.json']:
 target=attempt/p;target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(root/p,target)
(attempt/'inputs.json').write_text(json.dumps(inputs,indent=2)+'\n');shutil.copyfile(dest/'workflow.json',attempt/'workflow.json');shutil.copyfile(dest/'nodes/review.json',attempt/'review.json')
launch={'startedAt':datetime.now(timezone.utc).isoformat(),'role':role,'model':'gpt-6.1-sol','inputs':inputs,'attempt':str(attempt.relative_to(root))};(out/('final-'+role+'-launch.json')).write_text(json.dumps(launch,indent=2)+'\n')
with (attempt/'validation.json').open('w') as f:subprocess.run(['riela','workflow','validate',name,'--workflow-definition-dir',str(base),'--output','json'],check=True,stdout=f)
with (attempt/'run.log').open('w') as f:r=subprocess.run(['riela','workflow','run',name,'--workflow-definition-dir',str(base),'--working-dir',str(root),'--session-store',str(root/'.riela/sessions'),'--artifact-root',str(root/'.riela/artifacts'),'--max-steps','1','--output','jsonl'],stdout=f,stderr=subprocess.STDOUT)
launch.update(exitCode=r.returncode,finishedAt=datetime.now(timezone.utc).isoformat())
for line in (attempt/'run.log').read_text().splitlines():
 try:e=json.loads(line)
 except ValueError:continue
 if e.get('type')=='session_started':launch['sessionId']=e['sessionId'];break
if launch.get('sessionId'):
 runtime=json.loads((root/'.riela/artifacts'/launch['sessionId']/'runtime-snapshot.json').read_text());launch['runtimeStatus']=runtime['session']['status'];result=runtime.get('rootOutput')
 if result is not None:
  (out/('final-'+role+'-result.json')).write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');(attempt/'result.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
(out/('final-'+role+'-launch.json')).write_text(json.dumps(launch,indent=2)+'\n');(attempt/'launch.json').write_text(json.dumps(launch,indent=2)+'\n');(attempt/'manifest.json').write_text(json.dumps({'files':{str(p.relative_to(attempt)):sha(p) for p in attempt.rglob('*') if p.is_file()}},indent=2)+'\n');print(json.dumps(launch))
